// models/SupportTicket.js
const mongoose = require("mongoose");

const STATUSES = ["open", "in-progress", "resolved", "closed"];
const PRIORITIES = ["low", "medium", "high", "urgent"];

const supportTicketSchema = new mongoose.Schema(
  {
    // Human-readable ticket number — deepScode-YYYYMMDD-XXXX. Generated by
    // services/supportTicket.service.js via an atomic counter, never by
    // the client. This is the ID shown to users/admins; ObjectId is never
    // exposed as "the ticket number".
    ticketNumber: {
      type: String,
      required: true,
      unique: true,
      trim: true,
      index: true,
    },

    // Nullable — guest submissions have no linked account.
    user: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "User",
      default: null,
    },

    issueType: {
      type: String,
      required: [true, "Issue type is required"],
      trim: true,
      maxlength: [100, "Issue type cannot exceed 100 characters"],
    },
    subject: {
      type: String,
      required: [true, "Subject is required"],
      trim: true,
      maxlength: [150, "Subject cannot exceed 150 characters"],
    },
    description: {
      type: String,
      required: [true, "Description is required"],
      trim: true,
      maxlength: [3000, "Description cannot exceed 3000 characters"],
    },

    fullName: {
      type: String,
      required: [true, "Full name is required"],
      trim: true,
      maxlength: [100, "Full name cannot exceed 100 characters"],
    },
    email: {
      type: String,
      required: [true, "Email is required"],
      lowercase: true,
      trim: true,
      match: [/^[^\s@]+@[^\s@]+\.[^\s@]+$/, "Enter a valid email address"],
    },
    phone: { type: String, trim: true, default: "" },
    studentId: { type: String, trim: true, default: "" },

    status: {
      type: String,
      enum: { values: STATUSES, message: `Status must be one of: ${STATUSES.join(", ")}` },
      default: "open",
    },
    priority: {
      type: String,
      enum: { values: PRIORITIES, message: `Priority must be one of: ${PRIORITIES.join(", ")}` },
      default: "medium",
    },

    // Nullable — assigned staff/admin/counsellor member handling this ticket.
    assignedTo: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "User",
      default: null,
    },

    adminReply: { type: String, trim: true, default: "" },

    // Nullable — set once this ticket has been converted into an Inquiry.
    // Presence of this field is what prevents duplicate Inquiry creation.
    inquiry: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "Inquiry",
      default: null,
    },

    resolvedAt: { type: Date, default: null },
  },
  { timestamps: true }
);

supportTicketSchema.index({ status: 1, priority: 1 });
supportTicketSchema.index({ user: 1, createdAt: -1 });
supportTicketSchema.index({ assignedTo: 1 });
supportTicketSchema.index({ issueType: 1 });

const SupportTicket = mongoose.model("SupportTicket", supportTicketSchema);

module.exports = SupportTicket;
module.exports.STATUSES = STATUSES;
module.exports.PRIORITIES = PRIORITIES;